#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov M1 front — page Commentaires (liste + Kanban + filtres + tableau de bord + volet detail avec transitions & fil) + helper client teste. Purement ADDITIF (nouvelle route). A appliquer apres 04_apply_m1_comments.py."""
import base64, os, sys, subprocess
FILES={"src/lib/commentClient.ts": "", "src/lib/__tests__/commentClient.test.ts": "", "src/app/projects/[id]/comments/page.tsx": ""}
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! échec (rc=%d) — rien poussé."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:])
    print("== Bilnov M1 front (page Commentaires) =="); 
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
    print("[tests"+(" + build" if build else "")+"]")
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Bilnov M1 front (page Commentaires) (route /projects/[id]/comments). Aucun git push.")
if __name__=='__main__': main()
